/**
 * Look up a function name by library and LVO offset.
 * Returns the function name or undefined if not found.
 */
export function getLvoName(library: string, offset: number): string | undefined {
  const map = ALL_LVO_NAMES[library.toLowerCase()];
  return map ? map[offset] : undefined;
}
